import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  Img,
  interpolate,
} from '../remotionShim';
{/* Start Google Fonts Loader */}
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map((f) => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */}



export type GlowingIconProps = Record<string, any>;

const GlowingIcon: React.FC<GlowingIconProps> = ({
  backgroundColor = "#000000",
  transparentBackground = false,
  durationInSeconds = 10,
  imageUrl = "https://cdn-icons-png.flaticon.com/512/5156/5156315.png",
  imageSize = 400,
  glowRadius = 40,
  pulseSpeed = 2,
}) => {
  // Even if no text is currently used, we initialize the loader to adhere to strict structure rules.
  useFontLoader(["Inter"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Background Logic
  const finalBgColor = transparentBackground ? "transparent" : backgroundColor;

  // Pulse Logic
  // We use a sine wave based on the frame count and pulse speed
  const wave = Math.sin((frame / fps) * pulseSpeed * Math.PI);
  
  // Interpolate the wave (-1 to 1) to usable animation values
  const scale = interpolate(wave, [-1, 1], [1, 1.05], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const glowOpacity = interpolate(wave, [-1, 1], [0.4, 0.7], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const glowScale = interpolate(wave, [-1, 1], [1.1, 1.25], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  return (
    <AbsoluteFill
      style={{
        backgroundColor: finalBgColor,
        justifyContent: "center",
        alignItems: "center",
      }}
    >
      <div
        style={{
          position: "relative",
          width: imageSize,
          height: imageSize,
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
        }}
      >
        {/* Ambient Glow Layer - Blurred duplicate of the image */}
        <Img
          src={imageUrl}
          style={{
            position: "absolute",
            width: "100%",
            height: "100%",
            filter: `blur(${glowRadius}px) saturate(1.5)`,
            opacity: glowOpacity,
            transform: `scale(${glowScale})`,
            transition: "none", // STRICT ANIMATION RULE
          }}
        />

        {/* Main Image Layer */}
        <Img
          src={imageUrl}
          style={{
            position: "relative",
            width: "100%",
            height: "100%",
            transform: `scale(${scale})`,
            zIndex: 1,
            transition: "none", // STRICT ANIMATION RULE
            filter: "drop-shadow(0px 0px 10px rgba(0,0,0,0.3))", // Slight shadow for separation
          }}
        />
      </div>
    </AbsoluteFill>
  );
};

export default GlowingIcon;